package com.rork.rockscout.data

/** A U.S. national or state park with rockhounding or geological relevance. */
data class StatePark(
    val id: String,            // unique slug
    val name: String,
    val state: String,         // state code, e.g. "AZ"
    val region: String,        // "Tucson, Arizona"
    val description: String,
    val latitude: Double,
    val longitude: Double,
    val hasCamping: Boolean,
    val feeInfo: String,
    val website: String?,
    val addedAtMs: Long = 0L,            // epoch ms when added; 0 = legacy (no badge)
    val isNationalPark: Boolean = false, // true for US National Parks
) {
    /** True when this park was added within the last 7 days. */
    fun isNew(): Boolean {
        if (addedAtMs == 0L) return false
        val ageMs = System.currentTimeMillis() - addedAtMs
        return ageMs in 0..(SEVEN_DAYS_MS)
    }

    private companion object {
        const val SEVEN_DAYS_MS = 7L * 24 * 60 * 60 * 1000
    }
}

