        StatePark("roxborough-co", "Roxborough State Park", "CO", "Littleton, Colorado", "A National Natural Landmark featuring dramatic tilted red sandstone Fountain Formation rocks — the same formation seen at Red Rocks. Ancient Pennsylvanian-Permian geology with visible angular unconformities.", 39.4720, -105.1080, false, "$10/vehicle", "https://cpw.state.co.us/roxborough"),
