        StatePark("eldorado-co", "Eldorado Canyon State Park", "CO", "Boulder, Colorado", "World-renowned for its dramatic sandstone cliffs — the Fountain Formation exposed in vertical walls up to 800 feet. The canyon contains visible cross-bedding and ancient stream deposits.", 39.9290, -105.2890, false, "$10/vehicle", "https://cpw.state.co.us/eldorado"),
        StatePark("lory-co", "Lory State Park", "CO", "Bellvue, Colorado", "Exposes Precambrian metamorphic rocks and sedimentary formations along the Horsetooth Reservoir. Visible pegmatite dikes and migmatite throughout the park's trails.", 40.5560, -105.2460, false, "$10/vehicle", "https://cpw.state.co.us/lory"),
        StatePark("sylvan-lake-co", "Sylvan Lake State Park", "CO", "Eagle, Colorado", "Surrounded by the White River National Forest, featuring sedimentary rock formations and glacial carved valleys. Excellent examples of Leadville limestone and Sawatch quartzite.", 39.6420, -106.6620, true, "$10/vehicle", "https://cpw.state.co.us/sylvan"),
