        StatePark("table-rock-sc", "Table Rock State Park", "SC", "Pickens, South Carolina", "Iconic Table Rock granite dome of the Blue Ridge Province. Exposes Precambrian-age Henderson Gneiss with dramatic glacial-era weathering.", 35.0300, -82.7000, true, "$5/adult", "https://southcarolinaparks.com/table-rock"),
        StatePark("hunting-island-sc", "Hunting Island State Park", "SC", "Hunting Island, South Carolina", "Barrier island with dynamic beach erosion exposing Pleistocene and Holocene coastal deposits. Fossil shark teeth occasionally found.", 32.3700, -80.4400, true, "$5/adult", "https://southcarolinaparks.com/hunting-island"),
        StatePark("jones-gap-sc", "Jones Gap State Park", "SC", "Marietta, South Carolina", "Blue Ridge Escarpment exposing Henderson Gneiss and Brevard Zone mylonitic rocks. The Middle Saluda River exposes dramatic metamorphic bedrock geology.", 35.1350, -82.6140, false, "$5/adult", "https://southcarolinaparks.com/jones-gap"),
        StatePark("ool-bay-sc", "Sesquicentennial State Park", "SC", "Columbia, South Carolina", "Exposes Piedmont metamorphic rocks including slate and phyllite of the Carolina terrane. Visible saprolite and ancient weathering profiles in the red clay hills.", 34.0800, -80.9300, true, "$5/adult", "https://southcarolinaparks.com/sesquicentennial"),
        StatePark("lipton-sc", "Landsford Canal State Park", "SC", "Chester, South Carolina", "Exposes Paleozoic-age metamorphic rocks of the Piedmont along the Catawba River. Historic canal carved into granite gneiss bedrock — visible rock formations in the river channel.", 34.5800, -80.8800, false, "$5/adult", "https://southcarolinaparks.com/landsford"),
        StatePark("cherokee-sc", "Cherokee Foothills Scenic Highway / Table Rock Vicinity", "SC", "Pickens, South Carolina", "Exposes Blue Ridge Province metamorphic rocks along the scenic Highway 11 corridor. Visible Henderson Gneiss, granitic intrusions, and ancient thrust-fault structures at the edge of the mountains.", 35.0200, -82.5800, false, "Free", "https://southcarolinaparks.com/cherokee-foothills"),
        StatePark("hampton-sc", "Hampton Plantation State Historic Site", "SC", "McClellanville, South Carolina", "Exposes Santee Limestone — Eocene-age marine deposits. Fossil shells and ancient coastal plain sediments visible along the Santee River.", 33.3400, -79.5800, false, "Free", "https://southcarolinaparks.com/hampton"),

        // ── South Dakota ────────────────────────────────────────────────────
        StatePark("badlands-np-sd", "Badlands National Park", "SD", "Interior, South Dakota", "244,000 acres of eroded buttes, pinnacles, and spires in Oligocene Brule and Chadron Formations. One of the world's richest Oligocene mammal fossil beds — titanothere, oreodont, and ancient rhino bones. The White River Badlands expose 30-50 million years of sedimentary geology. Visible yellow and red paleosol horizons.", 43.8554, -102.3395, true, "$30/vehicle (7-day)", "https://www.nps.gov/badl", isNationalPark = true),
        StatePark("wind-cave-np-sd", "Wind Cave National Park", "SD", "Hot Springs, South Dakota", "One of the world's longest and oldest caves — formed in 320-million-year-old Pahasapa Limestone (Mississippian). Famous for boxwork formations — delicate calcite fins filling fractures. Frostwork, popcorn, and dogtooth spar cave formations. Surface geology includes Red Valley and the Madison Limestone.", 43.5700, -103.4700, false, "Free (cave tour fees apply)", "https://www.nps.gov/wica", isNationalPark = true),
        StatePark("custer-state-sd", "Custer State Park", "SD", "Custer, South Dakota", "Granite peaks of the Black Hills including Harney Peak granite. Exposes 1.7-billion-year-old Precambrian metamorphic and igneous rocks.", 43.7000, -103.5000, true, "$20/vehicle", "https://gfp.sd.gov/custer-state-park"),
        StatePark("bear-butte-sd", "Bear Butte State Park", "SD", "Sturgis, South Dakota", "Geological laccolith — magma intrusion that pushed up sedimentary layers. Exposes phonolite porphyry similar to Devils Tower.", 44.4400, -103.4600, false, "$6/vehicle", "https://gfp.sd.gov/bear-butte"),
        StatePark("palisades-sd", "Palisades State Park", "SD", "Garretson, South Dakota", "Dramatic Sioux Quartzite cliffs along the Split Rock River. Exposes 1.6-billion-year-old pink quartzite — some of the oldest rock in South Dakota.", 43.7100, -96.5000, true, "$6/vehicle", "https://gfp.sd.gov/palisades"),
        StatePark("adams-homestead-sd", "Adams Homestead and Nature Preserve", "SD", "McCook Lake, South Dakota", "Exposes loess deposits along the Missouri River valley. Visible glacial-age wind-blown silt over Pierre Shale bedrock.", 42.5200, -96.4800, false, "Free", "https://gfp.sd.gov/adams-homestead"),
        StatePark("newton-hills-sd", "Newton Hills State Park", "SD", "Canton, South Dakota", "Exposes Sioux Quartzite bedrock — 1.6-billion-year-old pink quartzite. Glacial till deposits over the ancient Precambrian bedrock visible in valley walls.", 43.0800, -96.7800, true, "$6/vehicle", "https://gfp.sd.gov/newton-hills"),
        StatePark("union-grove-sd", "Union Grove State Park", "SD", "Beresford, South Dakota", "Exposes glacial till over Sioux Quartzite bedrock. Visible ancient Precambrian quartzite boulders transported by Pleistocene glaciers.", 43.0300, -96.7800, true, "$6/vehicle", "https://gfp.sd.gov/union-grove"),
        StatePark("richmond-lake-sd", "Richmond Lake Recreation Area", "SD", "Aberdeen, South Dakota", "Exposes glacial drift deposits of the Coteau des Prairies. Visible glacial till and ancient glacial lake sediments from the James Lobe of the Laurentide Ice Sheet.", 45.4800, -98.4400, true, "$6/vehicle", "https://gfp.sd.gov/richmond-lake"),

        // ── Tennessee ───────────────────────────────────────────────────────
        StatePark("great-smoky-np-tn", "Great Smoky Mountains National Park", "TN", "Gatlinburg, Tennessee", "America's most-visited national park. Exposes 800-million-year-old Ocoee Supergroup metamorphic rocks — sandstone, slate, and metasiltstone. Thunderhead Sandstone forms the highest ridges. Visible folding and faulting from the Alleghenian orogeny. Alum Cave exposes Anakeesta Formation pyritic slate.", 35.6110, -83.4900, true, "Free", "https://www.nps.gov/grsm", isNationalPark = true),
        StatePark("fall-creek-tn", "Fall Creek Falls State Park", "TN", "Pikeville, Tennessee", "256-foot waterfall — one of the highest in the eastern US. Carved into Mississippian-age Monteagle Limestone with spectacular gorge geology.", 35.6800, -85.3500, true, "$5/vehicle", "https://www.tnstateparks.com/fall-creek-falls"),
        StatePark("cummins-tn", "Cummins Falls State Park", "TN", "Cookeville, Tennessee", "75-foot waterfall into a deep gorge carved through Mississippian limestone. Rock pools and scenic waterfall geology.", 36.2800, -85.6100, false, "$5/vehicle", "https://www.tnstateparks.com/cummins-falls"),
        StatePark("pickett-tn", "Pickett State Park", "TN", "Jamestown, Tennessee", "Cumberland Plateau geology with natural arches and rock shelters in Pennsylvanian sandstone. Contains delicate sandstone formations.", 36.5600, -84.7800, true, "$5/vehicle", "https://www.tnstateparks.com/pickett"),
        StatePark("rock-island-tn", "Rock Island State Park", "TN", "Rock Island, Tennessee", "Dramatic waterfalls and gorge carved into Mississippian-age limestone. Great Falls of the Caney Fork exposes fossil-rich limestone strata.", 35.8060, -85.6350, true, "$5/vehicle", "https://www.tnstateparks.com/rock-island"),
        StatePark("south-cumberland-tn", "South Cumberland State Park", "TN", "Sewanee, Tennessee", "Sewanee Conglomerate forms dramatic cliffline on the Cumberland Plateau. Stone Door and Fiery Gizzard features expose Pennsylvanian-age sandstone.", 35.1950, -85.7240, true, "Free", "https://www.tnstateparks.com/south-cumberland"),
        StatePark("radnor-lake-tn", "Radnor Lake State Park", "TN", "Nashville, Tennessee", "Exposes Ordovician-age limestone and shale of the Central Basin. Visible fossil beds and weathered limestone outcrops along the lake shore trails.", 36.0600, -86.8100, false, "Free", "https://www.tnstateparks.com/radnor-lake"),
        StatePark("long-hunter-tn", "Long Hunter State Park", "TN", "Hermitage, Tennessee", "Exposes Ordovician-age Lebanon Limestone along J. Percy Priest Lake. Visible fossil crinoids and brachiopods in limestone outcrops along the shoreline.", 36.1700, -86.6100, true, "Free", "https://www.tnstateparks.com/long-hunter"),
        StatePark("montgomery-bell-tn", "Montgomery Bell State Park", "TN", "Burns, Tennessee", "Exposes Mississippian-age Warsaw Limestone and Fort Payne Formation. Visible limestone outcrops and karst features in the Western Highland Rim terrain.", 36.1900, -87.1900, true, "Free", "https://www.tnstateparks.com/montgomery-bell"),
        StatePark("cumberland-mountain-tn", "Cumberland Mountain State Park", "TN", "Crossville, Tennessee", "Exposes Pennsylvanian-age sandstone and conglomerate of the Cumberland Plateau. Dramatic rock shelters and cliff formations visible throughout the park.", 35.9000, -85.0800, true, "Free", "https://www.tnstateparks.com/cumberland-mountain"),

        // ── Texas ───────────────────────────────────────────────────────────
        StatePark("big-bend-np-tx", "Big Bend National Park", "TX", "Big Bend, Texas", "Dramatic desert geology — the Chisos Mountains volcanic caldera exposes Tertiary igneous rocks. Ross Maxwell Scenic Drive reveals the McDougal Fault, Santa Elena Limestone cliffs, and ancient marine deposits. Fossil-rich Aguja and Javelina Formations contain dinosaur bones. Hot springs along the Rio Grande emerge from Tertiary volcanic rocks.", 29.1250, -103.2425, true, "$30/vehicle (7-day)", "https://www.nps.gov/bibe", isNationalPark = true),
        StatePark("guadalupe-mountains-np-tx", "Guadalupe Mountains National Park", "TX", "Salt Flat, Texas", "Contains the four highest peaks in Texas, including Guadalupe Peak (8,751 ft). Exposes the world's finest exposed Permian fossil reef — the ancient Capitan Reef. El Capitan is a massive limestone cliff. McKittrick Canyon reveals dramatic fossil-rich reef deposits. Carlsbad Caverns is part of the same reef system.", 31.9210, -104.8730, true, "$30/vehicle (7-day, Dec-Mar free)", "https://www.nps.gov/gumo", isNationalPark = true),
        StatePark("enchanted-rock-tx", "Enchanted Rock State Natural Area", "TX", "Fredericksburg, Texas", "One of the largest batholiths in the United States — a massive pink granite dome rising 425 feet above the surrounding Hill Country. Exfoliation domes and rock pools showcase Precambrian geology dating back 1 billion years.", 30.5060, -98.8180, true, "$8/vehicle", "https://tpwd.texas.gov/enchantedrock"),
        StatePark("palo-duro-tx", "Palo Duro Canyon State Park", "TX", "Canyon, Texas", "The 'Grand Canyon of Texas' exposes Permian and Triassic sedimentary rocks — dramatic red, orange, and purple sandstone and shale layers carved by the Prairie Dog Town Fork Red River.", 34.9370, -101.6940, true, "$8/vehicle", "https://tpwd.texas.gov/palodurocanyon"),
        StatePark("caprock-tx", "Caprock Canyons State Park", "TX", "Quitaque, Texas", "Features dramatic caprock escarpment geology where the High Plains meet the Rolling Plains. Exposed red Permian sandstone and shale layers with visible unconformities.", 34.5180, -101.3720, true, "$8/vehicle", "https://tpwd.texas.gov/caprockcanyons"),
        StatePark("hueco-tx", "Hueco Tanks State Park & Historic Site", "TX", "El Paso, Texas", "Unique syenite porphyry rock formations with natural tanks (huecos) that trap rainwater. World-class bouldering and ancient rock art amid dramatic volcanic geology.", 31.9210, -106.0390, true, "$9/vehicle (reservations required)", "https://tpwd.texas.gov/huecotanks"),
        StatePark("seminole-tx", "Seminole Canyon State Park & Historic Site", "TX", "Comstock, Texas", "Limestone canyons with globally significant rock art dating back 4,000+ years. The geology exposes Cretaceous-era Edwards Limestone with fossil-rich layers.", 29.4480, -101.2840, true, "$8/vehicle", "https://tpwd.texas.gov/seminolecanyon"),
        StatePark("colorado-bend-tx", "Colorado Bend State Park", "TX", "Bend, Texas", "Features Gorman Cave — a limestone cave with spectacular formations. The park exposes Cretaceous limestone with abundant marine fossils and travertine deposits along springs.", 31.0180, -98.4790, true, "$5/vehicle", "https://tpwd.texas.gov/coloradobend"),
        StatePark("pedernales-falls-tx", "Pedernales Falls State Park", "TX", "Johnson City, Texas", "Pedernales Falls exposes ancient Cretaceous limestone layers carved by the Pedernales River. Dramatic cascading waterfalls over 300-million-year-old rock formations.", 30.3070, -98.2480, true, "$6/vehicle", "https://tpwd.texas.gov/pedernalesfalls"),
        StatePark("lost-maples-tx", "Lost Maples State Natural Area", "TX", "Vanderpool, Texas", "Limestone canyons with dramatic cliffs and spring-fed pools. The Edwards Plateau geology features fossil-rich Cretaceous limestone and unique karst formations.", 29.7380, -99.5490, true, "$6/vehicle", "https://tpwd.texas.gov/lostmaples"),
        StatePark("franklin-mountains-tx", "Franklin Mountains State Park", "TX", "El Paso, Texas", "Exposes Precambrian metamorphic rocks — the 1.25-billion-year-old Castner Marble and Mundy Breccia. Visible limestone, rhyolite, and granite formations. Texas's largest urban park.", 31.8400, -106.4200, true, "$5/vehicle", "https://tpwd.texas.gov/franklinmountains"),

        // ── Utah ────────────────────────────────────────────────────────────
        StatePark("arches-np-ut", "Arches National Park", "UT", "Moab, Utah", "Over 2,000 natural sandstone arches — the world's largest concentration. Entrada Sandstone arches formed by erosion of fins along parallel fractures. Delicate Arch stands 52 feet high. Fiery Furnace exposes complex jointing. Visible petrified dunes in the Navajo Sandstone below.", 38.7331, -109.5925, true, "$30/vehicle (7-day)", "https://www.nps.gov/arch", isNationalPark = true),
        StatePark("bryce-canyon-np-ut", "Bryce Canyon National Park", "UT", "Bryce Canyon, Utah", "Thousands of hoodoos — intricately eroded spires of the Claron Formation (limestone, siltstone, and mudstone). Frost-wedging and rainwater sculpt the colorful pink, orange, and white formations. Natural amphitheaters rather than a true canyon. Visible Grand Staircase strata sequence.", 37.5930, -112.1870, true, "$35/vehicle (7-day)", "https://www.nps.gov/brca", isNationalPark = true),
        StatePark("canyonlands-np-ut", "Canyonlands National Park", "UT", "Moab, Utah", "Vast canyon system carved by the Colorado and Green Rivers through Permian Cutler Formation sandstone. Island in the Sky mesa, Needles spires, and the Maze labyrinth. Upheaval Dome — a possible meteorite impact crater. Visible salt dome geology from the Paradox Formation.", 38.4634, -109.8710, true, "$30/vehicle (7-day)", "https://www.nps.gov/cany", isNationalPark = true),
        StatePark("capitol-reef-np-ut", "Capitol Reef National Park", "UT", "Torrey, Utah", "100-mile-long Waterpocket Fold — a classic monocline exposing 200 million years of sedimentary geology. Navajo Sandstone domes resemble the US Capitol dome (hence the name). Cathedral Valley features monolithic Entrada Sandstone formations. Fruita historic orchards in the canyon.", 38.3670, -111.2615, true, "$20/vehicle (7-day)", "https://www.nps.gov/care", isNationalPark = true),
        StatePark("zion-np-ut", "Zion National Park", "UT", "Springdale, Utah", "Dramatic Navajo Sandstone cliffs — some up to 2,200 feet tall. The Virgin River carved the spectacular Zion Canyon through cross-bedded Jurassic sandstone. Angels Landing exposes the ancient desert dune environment. The Narrows is a slot canyon with exposed sandstone stratification.", 37.2980, -113.0260, true, "$35/vehicle (7-day)", "https://www.nps.gov/zion", isNationalPark = true),
        StatePark("snow-canyon-ut", "Snow Canyon State Park", "UT", "Ivins, Utah", "Stunning red and white Navajo Sandstone formations with petrified sand dunes, lava flows, and cinder cones. The park showcases both ancient desert geology and recent volcanic activity.", 37.2050, -113.6490, false, "$10/vehicle", "https://stateparks.utah.gov/snowcanyon"),
        StatePark("dead-horse-ut", "Dead Horse Point State Park", "UT", "Moab, Utah", "Spectacular overlook of the Colorado River's gooseneck meanders through layered Permian and Pennsylvanian sedimentary rocks. Classic cutaway view of Canyonlands geology.", 38.4720, -109.7400, true, "$20/vehicle", "https://stateparks.utah.gov/deadhorsepoint"),
        StatePark("goblin-valley-ut", "Goblin Valley State Park", "UT", "Goblin Valley, Utah", "Thousands of hoodoos — weathered goblin-shaped rock formations carved from Entrada Sandstone. The soft sandstone creates otherworldly shapes from wind and water erosion.", 38.5680, -110.6420, false, "$15/vehicle", "https://stateparks.utah.gov/goblinvalley"),
        StatePark("coral-pink-ut", "Coral Pink Sand Dunes State Park", "UT", "Kanab, Utah", "Vibrant pink-orange sand dunes formed from Navajo Sandstone erosion. The sand grains are tinted by iron oxides — a living example of how sandstone is formed and eroded.", 37.0240, -112.3590, true, "$10/vehicle", "https://stateparks.utah.gov/coralpinksanddunes"),
        StatePark("antelope-island-ut", "Antelope Island State Park", "UT", "Syracuse, Utah", "The largest island in the Great Salt Lake features Precambrian metamorphic and igneous rocks — some of the oldest visible rocks in Utah. Fringing mineral deposits along the shoreline.", 41.0330, -112.2200, true, "$15/vehicle", "https://stateparks.utah.gov/antelopeisland"),
        StatePark("wasatch-mountain-ut", "Wasatch Mountain State Park", "UT", "Midway, Utah", "Features exposed sedimentary and metamorphic rocks of the Wasatch Range. Glacial moraines and ancient river deposits visible along trails. Mineral springs in the area.", 40.5180, -111.3680, true, "$10/vehicle", "https://stateparks.utah.gov/wasatchmountain"),
        StatePark("edge-of-world-ut", "Edge of the Cedars State Park", "UT", "Blanding, Utah", "Ancient Puebloan site with exposed Morrison Formation rocks — the same formation that yields dinosaur fossils across the Colorado Plateau. Rich in Jurassic-age geology.", 37.6260, -109.4720, false, "$5/vehicle", "https://stateparks.utah.gov/edgeofthecedars"),
        StatePark("huntington-ut", "Huntington State Park", "UT", "Huntington, Utah", "Reservoir park exposing Cretaceous-age sedimentary rocks of the Wasatch Plateau. Coal deposits and fossil-bearing shales visible in nearby road cuts.", 39.3340, -111.0660, true, "$10/vehicle", "https://stateparks.utah.gov/huntington"),
        StatePark("kodachrome-basin-ut", "Kodachrome Basin State Park", "UT", "Cannonville, Utah", "67 sedimentary sandstone spires (pipes) — unique geologic features formed when ancient springs deposited minerals that cemented sand. Exposes Entrada and Carmel Formations.", 37.1670, -111.9840, true, "$10/vehicle", "https://stateparks.utah.gov/kodachromebasin"),

        // ── Virginia ────────────────────────────────────────────────────────
        StatePark("shenandoah-np-va", "Shenandoah National Park", "VA", "Luray, Virginia", "Skyline Drive along the Blue Ridge crest. Exposes ancient Grenville-age basement rocks (1.1 billion years old) — granitic gneiss and the Old Rag Granite. Catoctin Greenstone — metamorphosed basalt flows. Visible at Stony Man and Hawksbill summits. Rockfish Gap fault zone and the Blue Ridge anticlinorium.", 38.6650, -78.4400, true, "$35/vehicle (7-day)", "https://www.nps.gov/shen", isNationalPark = true),
        StatePark("natural-bridge-va", "Natural Bridge State Park", "VA", "Natural Bridge, Virginia", "215-foot natural limestone arch carved by Cedar Creek. A National Historic Landmark exposing Ordovician-age Beekmantown dolomite.", 37.6300, -79.5400, false, "$9/adult", "https://www.dcr.virginia.gov/natural-bridge"),
        StatePark("breaks-interstate-va", "Breaks Interstate Park", "VA", "Breaks, Virginia", "'Grand Canyon of the South' — 1,600-foot deep gorge through Pennsylvanian sandstone. Dramatic cliff exposures of the Russell Fork.", 37.3000, -82.3200, true, "$5/vehicle", "https://www.breakspark.com"),
        StatePark("grayson-highlands-va", "Grayson Highlands State Park", "VA", "Mouth of Wilson, Virginia", "Highest point in Virginia with exposures of Mount Rogers rhyolite — some of the oldest volcanic rock in Virginia. Granitic intrusions visible.", 36.6200, -81.4600, true, "$7/vehicle", "https://www.dcr.virginia.gov/grayson-highlands"),
        StatePark("wild-cave-va", "Wilderness Road State Park", "VA", "Ewing, Virginia", "Exposes Newman Limestone Ridge and Cumberland Mountain sandstone. Visible karst features and cave entrances in the Mississippian limestone.", 36.6330, -83.5530, false, "Free", "https://www.dcr.virginia.gov/wilderness-road"),
        StatePark("leesylvania-va", "Leesylvania State Park", "VA", "Woodbridge, Virginia", "Exposes Potomac Group Cretaceous-age sediments — ancient river and floodplain deposits. Visible fossil wood and ironstone concretions in the coastal plain strata.", 38.6300, -77.2400, true, "$7/vehicle", "https://www.dcr.virginia.gov/leesylvania"),
        StatePark("mason-neck-va", "Mason Neck State Park", "VA", "Lorton, Virginia", "Exposes Potomac Group sedimentary deposits. Visible ancient Cretaceous river channel deposits and fossil-bearing layers along the Potomac River shoreline.", 38.4700, -77.1800, true, "$7/vehicle", "https://www.dcr.virginia.gov/mason-neck"),
        StatePark("york-river-va", "York River State Park", "VA", "Williamsburg, Virginia", "Exposes Miocene-age Eastover Formation and Pliocene-age Yorktown Formation marine sediments. Fossil shark teeth, whale bones, and shells found along the river cliffs.", 37.4100, -76.6300, true, "$7/vehicle", "https://www.dcr.virginia.gov/york-river"),
        StatePark("holliday-lake-va", "Holliday Lake State Park", "VA", "Appomattox, Virginia", "Exposes Piedmont metamorphic rocks — phyllite and quartzite of the Virginia Volcanic Plutonic Assemblage. Visible ancient volcanic and sedimentary structures.", 37.3700, -78.7300, true, "$7/vehicle", "https://www.dcr.virginia.gov/holliday-lake"),

        // ── Vermont ─────────────────────────────────────────────────────────
        StatePark("smugglers-notch-vt", "Smugglers' Notch State Park", "VT", "Cambridge, Vermont", "Dramatic narrow pass between Mount Mansfield and Spruce Peak. Exposes Precambrian schist and quartzite of the Green Mountains.", 44.5400, -72.7900, true, "$5/vehicle", "https://vtstateparks.com/smugglers-notch"),
        StatePark("quechee-vt", "Quechee State Park", "VT", "Quechee, Vermont", "Home to Vermont's deepest gorge — 165 feet deep — carved by the Ottauquechee River through Devonian quartzite and schist.", 43.6400, -72.4200, true, "$5/vehicle", "https://vtstateparks.com/quechee"),
        StatePark("mt-phil-vt", "Mount Philo State Park", "VT", "Charlotte, Vermont", "Exposes Champlain Valley sedimentary rocks — Ordovician limestone and shale. Dramatic overlook of Lake Champlain and the Adirondacks from the summit.", 44.3540, -73.1770, true, "$4/vehicle", "https://vtstateparks.com/philomtn"),
        StatePark("dunder-rocks-vt", "Dunder Rocks State Park / Emerald Lake", "VT", "East Dorset, Vermont", "Exposes Dorset Formation marble — Vermont's famous white marble quarry district. Visible marble outcrops and historic quarry faces.", 43.2270, -73.0430, true, "$5/vehicle", "https://vtstateparks.com/emeraldlake"),
        StatePark("lake-carmi-vt", "Lake Carmi State Park", "VT", "Franklin, Vermont", "Exposes Cambrian-age Dunham Dolomite and Cheshire Quartzite. The lake sits in a glacially carved basin over ancient sedimentary bedrock of northern Vermont.", 44.9500, -72.8500, true, "$4/vehicle", "https://vtstateparks.com/lakecarmi"),
        StatePark("half-moon-cove-vt", "Grand Isle State Park", "VT", "Grand Isle, Vermont", "Exposes Cambrian-age Dunham Dolomite along Lake Champlain shoreline. Visible fossiliferous dolomite and ancient shallow-marine sedimentary structures.", 44.7200, -73.2800, true, "$4/vehicle", "https://vtstateparks.com/grandisle"),
        StatePark("mount-mansfield-vt", "Mount Mansfield State Forest", "VT", "Stowe, Vermont", "Vermont's highest peak at 4,395 feet. Exposes Precambrian-age schist and quartzite of the Green Mountain core. Dramatic alpine glacial geology with visible cirques and arêtes.", 44.5200, -72.8200, true, "$3/vehicle", "https://vtstateparks.com/mountmansfield"),

        // ── Washington ──────────────────────────────────────────────────────
        StatePark("mount-rainier-np-wa", "Mount Rainier National Park", "WA", "Ashford, Washington", "Active 14,411-foot stratovolcano — the most glaciated peak in the lower 48. Exposes andesitic lava flows, pyroclastic deposits, and volcanic mudflow (lahar) deposits. Ice caves in the summit crater. Paradise lava flows visible. Carbon River exposes ancient metavolcanic basement rocks.", 46.8520, -121.7610, true, "$30/vehicle (7-day)", "https://www.nps.gov/mora", isNationalPark = true),
        StatePark("north-cascades-np-wa", "North Cascades National Park", "WA", "Sedro-Woolley, Washington", "Rugged alpine terrain exposing Skagit Gneiss Complex — 220-million-year-old metamorphic rocks. Dramatic glaciated peaks and visible thrust faults. Cascade batholith intrusions of granodiorite. Ruby Mountain and Hozomeen terrane exposures along Ross Lake.", 48.7750, -121.2020, false, "Free (no entrance fee)", "https://www.nps.gov/noca", isNationalPark = true),
        StatePark("olympic-np-wa", "Olympic National Park", "WA", "Port Angeles, Washington", "Three distinct ecosystems — alpine, temperate rainforest, and coastline. Exposes accreted oceanic terrane rocks — marine sedimentary and basaltic sequences. Hurricane Ridge reveals Eocene turbidites. Rialto Beach features dramatic sea stacks of the Coast Range basalt. Hoh Rainforest sits on glacial outwash deposits.", 47.8020, -123.6040, true, "$30/vehicle (7-day)", "https://www.nps.gov/olym", isNationalPark = true),
        StatePark("steamboat-wa", "Steamboat Rock State Park", "WA", "Electric City, Washington", "A massive basalt mesa rising 800 feet above Banks Lake — a remnant of the Grand Coulee's Ice Age flood carving. Spectacular columnar jointing in basalt.", 47.9150, -119.0470, true, "$10/vehicle", "https://parks.wa.gov/steamboat-rock"),
        StatePark("cape-disappointment-wa", "Cape Disappointment State Park", "WA", "Ilwaco, Washington", "Dramatic headland exposing Cape Disappointment conglomerate and volcanic basement rocks. The Columbia River bar geology and ancient beach deposits are visible.", 46.2750, -124.0550, true, "$10/vehicle", "https://parks.wa.gov/cape-disappointment"),
        StatePark("palouse-wa", "Palouse Falls State Park", "WA", "Washtucna, Washington", "Washington's state waterfall drops 200 feet into a dramatic basalt canyon carved by Ice Age floods. Exposes layered Grand Ronde basalt flows of the Columbia River Basalt Group.", 46.6640, -118.2110, false, "$10/vehicle", "https://parks.wa.gov/palouse-falls"),
